def solve(instance):
    n=instance['n']; edges=instance['edges']; adj=[[] for _ in range(n)]; ew={}
    for a,b,w in edges:
        adj[a].append((b,w)); adj[b].append((a,w)); ew[(a,b)]=w
    rng=random.Random(81731+n*31+len(edges)); deadline=time.process_time()+1.42
    bestval=-1; bestx=None
    def init(order, mode):
        x=[-1]*n
        for v in order:
            s=0
            for u,w in adj[v]:
                if x[u]>=0: s += w if x[u]==0 else -w
            if mode==0: x[v]=1 if s>0 else (0 if s<0 else rng.randrange(2))
            else: x[v]=(1 if s>0 else 0) if rng.random()<.8 else rng.randrange(2)
        return x
    def pair_improve(x):
        while True:
            g=[]
            for v in range(n):
                z=0
                for u,w in adj[v]: z += w if x[u]==x[v] else -w
                g.append(z)
            bg=0; bi=bj=-1
            for i in range(n):
                if g[i]>bg: bg=g[i]; bi=i; bj=-1
            for i in range(n):
                for j in range(i+1,n):
                    w=ew.get((i,j),0)
                    z=g[i]+g[j]+(2*w if x[i]!=x[j] else -2*w)
                    if z>bg: bg=z; bi=i; bj=j
            if bg<=0: return
            x[bi]^=1
            if bj>=0: x[bj]^=1
    def klpass(x):
        g=[sum(w if x[v]==x[u] else -w for u,w in adj[v]) for v in range(n)]
        locked=[False]*n; seq=[]; cum=0; best=0; bestk=0
        # choose random among tied best gain
        for step in range(n):
            mx=-10**9; candidates=[]
            for v in range(n):
                if not locked[v]:
                    if g[v]>mx: mx=g[v]; candidates=[v]
                    elif g[v]==mx: candidates.append(v)
            v=rng.choice(candidates); old=x[v]
            locked[v]=True; seq.append(v); cum+=g[v]
            if cum>best: best=cum; bestk=step+1
            x[v]^=1
            for u,w in adj[v]:
                if not locked[u]: g[u] += (2*w if x[u]==x[v] else -2*w)
            g[v]=-g[v]
        # currently all flipped, undo suffix to retain best prefix
        for v in seq[bestk:]: x[v]^=1
        return best
    def improve(x):
        pair_improve(x)
        # sequence move escape, iterating where gain positive
        for _ in range(3):
            d=klpass(x)
            if d<=0: break
            pair_improve(x)
    def value(x): return sum(w for a,b,w in edges if x[a]!=x[b])
    it=0
    while time.process_time()<deadline:
        if bestx is not None and it%4==3:
            x=bestx[:]; k=rng.randint(2,max(3,n//5))
            for v in rng.sample(range(n),k): x[v]^=1
        else:
            order=list(range(n)); rng.shuffle(order); x=init(order,it%2)
        improve(x); val=value(x)
        if val>bestval: bestval=val; bestx=x[:]
        it+=1
    return bestx

import time, random, math

def solve(instance):
    n=instance['n']; edges=instance['edges']; adj=[[] for _ in range(n)]; ew={}; deg=[0]*n
    for a,b,w in edges:
        adj[a].append((b,w)); adj[b].append((a,w)); ew[a,b]=w; deg[a]+=w; deg[b]+=w
    rng=random.Random(81731+n*31+len(edges)); deadline=time.process_time()+1.42
    bestval=-1; bestx=None
    def pair_improve(x):
        while True:
            g=[sum(w if x[v]==x[u] else -w for u,w in adj[v]) for v in range(n)]
            bg=0; bi=bj=-1
            for i,z in enumerate(g):
                if z>bg: bg=z;bi=i;bj=-1
            for i in range(n):
                for j in range(i+1,n):
                    w=ew.get((i,j),0)
                    z=g[i]+g[j]+(2*w if x[i]!=x[j] else -2*w)
                    if z>bg: bg=z;bi=i;bj=j
            if bg<=0:return
            x[bi]^=1
            if bj>=0:x[bj]^=1
    def construct(mode):
        if mode==0: return [rng.randrange(2) for _ in range(n)]
        if mode==2:
            order=sorted(range(n),key=lambda v:deg[v]*(0.75+0.5*rng.random()),reverse=True)
        else:
            order=list(range(n));rng.shuffle(order)
        x=[-1]*n
        for v in order:
            a=b=0
            for u,w in adj[v]:
                if x[u]==0:a+=w
                elif x[u]==1:b+=w
            d=a-b
            if mode==1:
                x[v]=1 if d>0 else 0 if d<0 else rng.randrange(2)
            else:
                t=4.0 if mode==3 else 10.0
                p0=1/(1+math.exp(max(-30,min(30,d/t))))
                x[v]=0 if rng.random()<p0 else 1
        return x
    def value(x):return sum(w for a,b,w in edges if x[a]!=x[b])
    it=0
    while time.process_time()<deadline:
        if bestx is not None and it%5==4:
            x=bestx[:]
            k=rng.randint(2,max(3,n//3))
            for v in rng.sample(range(n),k):x[v]^=1
        else:x=construct(it%4)
        pair_improve(x); val=value(x)
        if val>bestval:bestval=val;bestx=x[:]
        it+=1
    return bestx

