                    if z>bg:bg=z;bi=i;bj=j
            if bg<=0:return
            x[bi]^=1
            if bj>=0:x[bj]^=1
    def tabu(x,steps):
        g=gains_for(x); val=sum(w for a,b,w in edges if x[a]!=x[b]); bv=val; bx=x[:]
        until=[0]*n
        for t in range(1,steps+1):
            v=-1; bg=-10**9
            for i in range(n):
                if until[i]<t and g[i]>bg: v=i;bg=g[i]
