            x[v]^=1; val+=bg; g[v]=-bg
            for u,w in adj[v]:g[u]+=(2*w if x[u]==x[v] else -2*w)
            until[v]=t+rng.randint(5,10)
            if val>bv:bv=val;bx=x[:]
        pair_improve(bx)
        return bx
    def init(it):
        if it%3==0:return [rng.randrange(2) for _ in range(n)]
