import random, time

def solve(instance):
    n=instance['n']; edges=instance['edges']
    adj=[[] for _ in range(n)]
    for u,v,w in edges:
        adj[u].append((v,w)); adj[v].append((u,w))
    rng=random.Random(918273)
    best=[rng.randrange(2) for _ in range(n)]
    bestval=-1
    start=time.process_time(); deadline=start+1.40
    # For a given partition compute vertex flip gains and ascent to 1-flip optimum.
    def improve(x):
        gains=[0]*n
        for u in range(n):
            xu=x[u]
            s=0
            for v,w in adj[u]:
                s += w if x[v]==xu else -w
            gains[u]=s
        # best-improvement single flips, then pair flips, repeat
        while True:
            while True:
                u=max(range(n), key=gains.__getitem__)
                if gains[u] <= 0: break
                old=gains[u]; x[u]^=1; gains[u]=-old
                for v,w in adj[u]:
                    c=w if x[v]!=x[u] else -w # contribution before flip? after flip relation
                    # after move neighbor gain contribution is opposite of after-rel contribution
                    gains[v] -= 2*c
            # steepest improving pair (not including diagonal)
            bi=bj=-1; bg=0
            for i in range(n):
                xi=x[i]
                for j in range(i+1,n):
                    e=0
                    for v,w in adj[i]:
                        if v==j:
                            e = w if xi==x[j] else -w
                            break
                    z=gains[i]+gains[j]-2*e
                    if z>bg: bg=z; bi=i; bj=j
            if bi<0: break
            # flipping both; update gain arrays by sequential flips (gain of second may change)
            for u in (bi,bj):
                old=gains[u]; x[u]^=1; gains[u]=-old
                for v,w in adj[u]:
                    c=w if x[v]!=x[u] else -w
                    gains[v] -= 2*c
        return x, sum(g for g in gains if False)
    def cutval(x):
        return sum(w for u,v,w in edges if x[u]!=x[v])
    # random starts; limited by CPU time
    it=0
    while time.process_time()<deadline:
        if it%4==0:
            x=[rng.randrange(2) for _ in range(n)]
        else:
            # randomized greedy assignment over random vertex ordering
            order=list(range(n)); rng.shuffle(order)
            x=[-1]*n
            for u in order:
                s0=s1=0
                for v,w in adj[u]:
                    if x[v]==0: s0+=w
                    elif x[v]==1: s1+=w
                # probability favor side with less accumulated neighbor weight
                d=s0-s1
                # noise randomized among choices
                if d>0: p=1.0/(1.0+__import__('math').exp(min(30,d/18)))
                elif d<0: p=1.0/(1.0+__import__('math').exp(max(-30,d/18)))
                else: p=.5
                x[u]=0 if rng.random()<p else 1
        x,_=improve(x)
        val=cutval(x)
        if val>bestval: bestval=val; best=x[:]
        it+=1
    return best

