                v=max(range(n),key=g.__getitem__)
                if g[v]<=0:break
                old=x[v];x[v]^=1;g[v]=-g[v]
                for j,w in adj[v]:g[j]+=(-2*w if x[j]==old else 2*w)
        singles()
        # 3-exchange hill climb (also implicitly allows 1/2); repeat after every accepted triple
        count=0
        while count<30:
            bg=0; bi=bj=bk=-1
            for i in range(n-2):
                gi=g[i]
                for j in range(i+1,n-1):
                    eij=wm[i][j]; pair=gi+g[j]-(2*eij if x[i]==x[j] else -2*eij)
