                        if z>bg: bg=z;bi=i;bj=j;bk=k
            if bg<=0:break
            for v in (bi,bj,bk):
                old=x[v];x[v]^=1;g[v]=-g[v]
                for j,w in adj[v]:g[j]+=(-2*w if x[j]==old else 2*w)
            singles();count+=1
        z=cut(x)
        if z>bestval:bestval=z;best=x[:]
    while time.process_time()<start+.75:
        it+=1
        if it%4==0:x=[rng.randrange(2) for _ in range(n)]
