import time
import random
import math

def solve(instance):
    n = instance['n']
    edges = instance['edges']
    if n <= 0:
        return []

    adj = [[] for _ in range(n)]
    W = [[0] * n for _ in range(n)]
    degree = [0] * n
    seed = (n * 9176 + len(edges) * 104729) & 0xffffffff

    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
        W[u][v] = W[v][u] = w
        degree[u] += w
        degree[v] += w
        seed = (seed * 1000003 + (u + 1) * 9176 +
                (v + 1) * 6113 + w * 104729) & 0xffffffff

    rng = random.Random(seed)
    deadline = time.process_time() + 1.43
    best = None
    bestval = -1
    it = 0

    def value(x):
        return sum(w for u, v, w in edges if x[u] != x[v])

    def climb(x, do_pairs=False):
        gains = [
            sum(w if x[u] == x[v] else -w for v, w in adj[u])
            for u in range(n)
        ]

        while True:
            # Steepest single-vertex ascent.
            while True:
                u = max(range(n), key=gains.__getitem__)
                if gains[u] <= 0:
                    break
                x[u] ^= 1
                gains[u] = -gains[u]
                for v, w in adj[u]:
                    gains[v] += 2 * w if x[v] == x[u] else -2 * w

            if not do_pairs:
                return x

            # Find the best improving pair flip.
            bi = bj = -1
            bg = 0
            for i in range(n):
                gi = gains[i]
                xi = x[i]
                for j in range(i + 1, n):
                    w = W[i][j]
                    z = gi + gains[j] + (2 * w if xi != x[j] else -2 * w)
                    if z > bg:
                        bg, bi, bj = z, i, j

            if bg <= 0:
                return x

            # Apply both flips with exact incremental gain updates.
            for u in (bi, bj):
                x[u] ^= 1
                gains[u] = -gains[u]
                for v, w in adj[u]:
                    gains[v] += 2 * w if x[v] == x[u] else -2 * w

    def make_start(mode):
        if mode == 0:
            return [rng.randrange(2) for _ in range(n)]

        if mode == 4 and best is not None:
            x = best[:]
            k = rng.randint(2, max(3, n // 4))
            for v in rng.sample(range(n), k):
                x[v] ^= 1
            return x

        if mode == 2:
            order = sorted(
                range(n),
                key=lambda v: degree[v] * (0.75 + 0.5 * rng.random()),
                reverse=True
            )
        elif mode == 3:
            order = sorted(
                range(n),
                key=lambda v: degree[v] + rng.random() * 25,
                reverse=True
            )
        else:
            order = list(range(n))
            rng.shuffle(order)

        x = [-1] * n
        temp = rng.choice((2.5, 5.0, 9.0, 16.0))
        for v in order:
            a = b = 0
            for u, w in adj[v]:
                if x[u] == 0:
                    a += w
                elif x[u] == 1:
                    b += w

            d = a - b
            if mode == 1:
                x[v] = 1 if d > 0 else 0 if d < 0 else rng.randrange(2)
            else:
                p0 = 1.0 / (1.0 + math.exp(max(-30.0, min(30.0, d / temp))))
                x[v] = 0 if rng.random() < p0 else 1

        return x

    while time.process_time() < deadline:
        x = make_start(it % 5)
        x = climb(x, do_pairs=(it % 4 == 0))
        z = value(x)
        if z > bestval:
            bestval = z
            best = x[:]
        it += 1

    return best
