        while True:
            while True:
                u=max(range(n), key=gains.__getitem__)
                if gains[u] <= 0: break
                old=gains[u]; x[u]^=1; gains[u]=-old
                for v,w in adj[u]:
                    c=w if x[v]!=x[u] else -w # contribution before flip? after flip relation
                    # after move neighbor gain contribution is opposite of after-rel contribution
                    gains[v] -= 2*c
            # steepest improving pair (not including diagonal)
            bi=bj=-1; bg=0
            for i in range(n):
                xi=x[i]
                for j in range(i+1,n):
                    e=0
                    for v,w in adj[i]:
                        if v==j:
                            e = w if xi==x[j] else -w
                            break
                    z=gains[i]+gains[j]-2*e
                    if z>bg: bg=z; bi=i; bj=j
