import time, random

def solve(instance):
    n=instance['n']; edges=instance['edges']
    adj=[[] for _ in range(n)]
    for a,b,w in edges:
        adj[a].append((b,w)); adj[b].append((a,w))
    rng=random.Random(81731+n*31+len(edges))
    start=time.process_time(); deadline=start+1.42
    bestval=-1; bestx=None
    def init(order, mode):
        x=[-1]*n
        for v in order:
            # choose side weighted against already assigned
            s=0
            for u,w in adj[v]:
                if x[u]>=0: s += w if x[u]==0 else -w
            if mode==0: x[v]= 1 if s>0 else (0 if s<0 else rng.randrange(2))
            else:
                # probabilistic preference
                x[v]=(1 if s>0 else 0) if rng.random()<.8 else rng.randrange(2)
        return x
    def improve(x):
        # gains exact
        g=[0]*n
        for v in range(n):
            for u,w in adj[v]:
                if u>v: continue
                # handle once? calculate per endpoints below simpler
        for v in range(n):
            z=0
            for u,w in adj[v]: z += w if x[u]==x[v] else -w
            g[v]=z
        # steepest descent
        while True:
            v=max(range(n),key=g.__getitem__)
            if g[v]<=0: break
            x[v]^=1; g[v]=-g[v]
            for u,w in adj[v]:
                g[u] += -2*w if x[u]==x[v] else 2*w
        return x
    def value(x):
        return sum(w for a,b,w in edges if x[a]!=x[b])
    it=0
    while time.process_time()<deadline:
        if bestx is not None and it%4==3:
            x=bestx[:]
            # perturb k random distinct vertices
            k=rng.randint(2, max(3,n//5))
            for v in rng.sample(range(n),k): x[v]^=1
        else:
            order=list(range(n)); rng.shuffle(order)
            x=init(order, it%2)
        x=improve(x)
        val=value(x)
        if val>bestval: bestval=val; bestx=x[:]
        it+=1
    return bestx

