import time, random

def solve(instance):
    n=instance['n']; edges=instance['edges']
    adj=[[] for _ in range(n)]
    for a,b,w in edges:
        adj[a].append((b,w)); adj[b].append((a,w))
    rng=random.Random(81731+n*31+len(edges))
    start=time.process_time(); deadline=start+1.42
    bestval=-1; bestx=None
    def init(order, mode):
        x=[-1]*n
        for v in order:
            # choose side weighted against already assigned
            s=0
            for u,w in adj[v]:
                if x[u]>=0: s += w if x[u]==0 else -w
            if mode==0: x[v]= 1 if s>0 else (0 if s<0 else rng.randrange(2))
            else:
                # probabilistic preference
                x[v]=(1 if s>0 else 0) if rng.random()<.8 else rng.randrange(2)
        return x
    def improve(x):
        # gains exact
        g=[0]*n
        for v in range(n):
            for u,w in adj[v]:
                if u>v: continue
                # handle once? calculate per endpoints below simpler
        for v in range(n):
            z=0
            for u,w in adj[v]: z += w if x[u]==x[v] else -w
            g[v]=z
        # steepest descent
        while True:
            v=max(range(n),key=g.__getitem__)
            if g[v]<=0: break
            x[v]^=1; g[v]=-g[v]
            for u,w in adj[v]:
                g[u] += -2*w if x[u]==x[v] else 2*w
        return x
    def value(x):
        return sum(w for a,b,w in edges if x[a]!=x[b])
    it=0
    while time.process_time()<deadline:
        if bestx is not None and it%4==3:
            x=bestx[:]
            # perturb k random distinct vertices
            k=rng.randint(2, max(3,n//5))
            for v in rng.sample(range(n),k): x[v]^=1
        else:
            order=list(range(n)); rng.shuffle(order)
            x=init(order, it%2)
        x=improve(x)
        val=value(x)
        if val>bestval: bestval=val; bestx=x[:]
        it+=1
    return bestx

import random, time

def solve(instance):
    n=instance['n']; edges=instance['edges']
    adj=[[] for _ in range(n)]
    for u,v,w in edges:
        adj[u].append((v,w)); adj[v].append((u,w))
    rng=random.Random(918273)
    best=[rng.randrange(2) for _ in range(n)]
    bestval=-1
    start=time.process_time(); deadline=start+1.40
    # For a given partition compute vertex flip gains and ascent to 1-flip optimum.
    def improve(x):
        gains=[0]*n
        for u in range(n):
            xu=x[u]
            s=0
            for v,w in adj[u]:
                s += w if x[v]==xu else -w
            gains[u]=s
        # best-improvement single flips, then pair flips, repeat
        while True:
            while True:
                u=max(range(n), key=gains.__getitem__)
                if gains[u] <= 0: break
                old=gains[u]; x[u]^=1; gains[u]=-old
                for v,w in adj[u]:
                    c=w if x[v]!=x[u] else -w # contribution before flip? after flip relation
                    # after move neighbor gain contribution is opposite of after-rel contribution
                    gains[v] -= 2*c
            # steepest improving pair (not including diagonal)
            bi=bj=-1; bg=0
            for i in range(n):
                xi=x[i]
                for j in range(i+1,n):
                    e=0
                    for v,w in adj[i]:
                        if v==j:
                            e = w if xi==x[j] else -w
                            break
                    z=gains[i]+gains[j]-2*e
                    if z>bg: bg=z; bi=i; bj=j
            if bi<0: break
            # flipping both; update gain arrays by sequential flips (gain of second may change)
            for u in (bi,bj):
                old=gains[u]; x[u]^=1; gains[u]=-old
                for v,w in adj[u]:
                    c=w if x[v]!=x[u] else -w
                    gains[v] -= 2*c
        return x, sum(g for g in gains if False)
    def cutval(x):
        return sum(w for u,v,w in edges if x[u]!=x[v])
    # random starts; limited by CPU time
    it=0
    while time.process_time()<deadline:
        if it%4==0:
            x=[rng.randrange(2) for _ in range(n)]
        else:
            # randomized greedy assignment over random vertex ordering
            order=list(range(n)); rng.shuffle(order)
            x=[-1]*n
            for u in order:
                s0=s1=0
                for v,w in adj[u]:
                    if x[v]==0: s0+=w
                    elif x[v]==1: s1+=w
                # probability favor side with less accumulated neighbor weight
                d=s0-s1
                # noise randomized among choices
                if d>0: p=1.0/(1.0+__import__('math').exp(min(30,d/18)))
                elif d<0: p=1.0/(1.0+__import__('math').exp(max(-30,d/18)))
                else: p=.5
                x[u]=0 if rng.random()<p else 1
        x,_=improve(x)
        val=cutval(x)
        if val>bestval: bestval=val; best=x[:]
        it+=1
    return best

